def incrementar_direto(n):
    if isinstance(n,bool) or not isinstance(n,int) or n<0:
        raise ValueError('Entrada inválida')
    return '1'*(n+1)
for n in range(6):
    saida=incrementar_direto(n)
    assert len(saida)==n+1 and set(saida)=={'1'}
